const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,PARENT=process.env.PARENT_SHA,PARENT_BLOB=process.env.PARENT_BLOB,TARGET_BLOB=process.env.TARGET_BLOB,TARGET_HASH=process.env.TARGET_HASH,TARGET_BYTES=Number(process.env.TARGET_BYTES);
const assert=(x,m)=>{if(!x)throw new Error(m)};
const parent=cp.execFileSync('git',['show',`${PARENT}:${TARGET}`]);assert(cp.execSync(`git rev-parse ${PARENT}:${TARGET}`,{encoding:'utf8'}).trim()===PARENT_BLOB,'parent blob drift');
const src=parent.toString('utf8');const selector='body:is([data-page="mensagens"], [data-page="comunidade-interna"])\n  :is(.messages-composer, .community-room-composer) {';const start=src.indexOf(selector);assert(start>=0,'parent source selector missing');const end=src.indexOf('\n}',start);assert(end>start,'parent source rule end missing');const block=src.slice(start,end);assert((block.match(/\n  row-gap: 10px;/g)||[]).length===1,'parent source gap cardinality drift');const winnerMarker='/* v2.1 — composer draft row guard.';const wsec=src.indexOf(winnerMarker);assert(wsec>start,'winner section order drift');const ws=src.indexOf(selector,wsec);assert(ws>wsec,'winner selector missing');const we=src.indexOf('\n}',ws);assert((src.slice(ws,we).match(/\n  row-gap: 0;/g)||[]).length===1,'winner gap drift');
const rebuilt=Buffer.from(src.slice(0,start)+block.replace('\n  row-gap: 10px;','')+src.slice(end));const actual=fs.readFileSync(TARGET);assert(rebuilt.equals(actual),'independent candidate bytes differ from permanent');const hash=crypto.createHash('sha256').update(actual).digest('hex');assert(hash===TARGET_HASH,`hash drift ${hash}`);assert(actual.length===TARGET_BYTES,`bytes drift ${actual.length}`);assert(cp.execSync(`git hash-object ${TARGET}`,{encoding:'utf8'}).trim()===TARGET_BLOB,'target blob drift');console.log(`EXACT BYTE IDENTITY PASS|parent=${PARENT}|parentBlob=${PARENT_BLOB}|targetBlob=${TARGET_BLOB}|hash=${hash}|bytes=${actual.length}|decl=455->454|dead=1->0|staticCascadeRows=1`);
